class Points(NodeData):
    def __init__(self, points):
        self.points = points
        points_vtk = servermanager.Fetch(points).GetPointData()
        num_arrays = points_vtk.GetNumberOfArrays()
        self.array_names = []

        for i in range(num_arrays):
            self.array_names.append(points_vtk.GetArrayName(i))

    def __getstate__(self):
        state = self.__dict__.copy()
        state["points"] = None
        return state

    def save(self, dirname):
        super().save(dirname)
        SaveData(f"{dirname}/points.pvd", self.points)

    @classmethod
    def load(cls, dirname):
        base = super().load(dirname)
        points = PVDReader(FileName=f"{dirname}/points.pvd")
        points.PointArrays = base.array_names
        base.points = points
        return base

    @classmethod
    def get_mcp_name(cls):
        return "points"

def _export_points(points, gt_arrayname, filename, new_arrayname, map, map_name, map_length):

    if filename[-4:] not in [".vtk", ".pvd"]:
        raise ValueError("Currently only VTK legacy data (.vtk) and ParaView data (.pvd) are supported for exporting points.")

    if len(map) != map_length:
        raise Exception(f"The length of {map_name} must be {map_length}")

    os.makedirs(os.path.dirname(os.path.abspath(filename)), exist_ok=True)

    filter = categorical_map_filter(points, gt_arrayname, map, -1, new_arrayname)
    SaveData(filename, filter)

    Delete(filter)

