class PointsEmbedding(NodeData):

    def __init__(self, points, radius, array_name, lut):
        self.points = points
        self.array_name = array_name
        self.lut = lut
        self.radius = radius

    def __getstate__(self):
        state = self.__dict__.copy()
        state["points"] = None
        return state

    def visualize(self, renderView):
        spheres = ttk.TTKIcospheresFromPoints(Input=self.points)
        spheres.Radius = self.radius

        display = Show(spheres, renderView, 'GeometryRepresentation')

        lut = GetColorTransferFunction(self.array_name)
        lut.RGBPoints = self.lut
        lut.ScalarRangeInitialized = 1.0

        display.LookupTable = lut
        display.ColorArrayName = ['POINTS', self.array_name]

    @classmethod
    def get_mcp_name(cls):
        return "points_embedding"

